var a=[{title:`Începător`,text:`Poți avea puțină experiență constantă de antrenament cu rezistență, poți reveni după o pauză lungă sau poți fi nou într-o mișcare. Exercițiile simple, exersarea repetată a tehnicii, sarcinile moderate și câteva serii de lucru bune se potrivesc acestei etape. Progresul rapid de la început vine adesea dintr-o coordonare mai bună și din familiarizare, nu doar din țesut muscular nou.`},{title:`Intermediar`,text:`Faci constant tiparele principale, îți poți estima efortul, îți repeți tehnica de la o sesiune la alta și progresezi prin schimbări planificate ale sarcinii sau ale repetărilor. Poate fi nevoie să împarți efortul pe mai multe zile, să numeri seriile grele și să fii mai atent la refacere și la platouri.`},{title:`Avansat`,text:`Avansat înseamnă o istorie lungă de practică productivă într-o anumită disciplină, cu un progres care a devenit lent. O planificare mai complexă poate ajuta, deși complexitatea nu este o realizare în sine. Cineva avansat la alergare poate fi totuși începător la genuflexiunile cu bara.`},{title:`Verificări utile`,text:`Poți face o genuflexiune sau o flexie din șold printr-o amplitudine controlată? Poți face o variantă de flotare fără să îți pierzi poziția corpului? Știi cum se simte o serie cu două repetări în rezervă? Sunt observații de coaching, nu teste universale de reușit sau picat. Niciun număr de flotări, nicio greutate la genuflexiune și nicio durată în luni de antrenament nu clasifică corect pe toată lumea.`},{title:`Ce înseamnă pentru programul tău`,text:`Două sau trei sesiuni pentru tot corpul, construite pe tiparele de bază de mișcare, sunt adesea suficiente pentru un începător. Un sportiv antrenat poate avea nevoie de mai mult volum săptămânal sau de exerciții mai specifice. Ambele urmează aceleași principii: specificitatea, progresia treptată și refacerea.`},{title:`Folosind TrainUp`,text:`Setează-ți nivelul de pregătire în Profil conform cu ceea ce poți face acum, nu cu ceea ce speri să faci. Dacă revii după o pauză, începe cu sarcini mai ușoare și mai puțin volum. Actualizează nivelul pe măsură ce tehnica, constanța și toleranța ți se îmbunătățesc.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`CDC: cum începi în siguranță`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};